   186	
   187	  /*************************** Product Detail and Category ********************/
   188	  const { productId } = useParams<{ productId?: string }>();
   189	  const urlParams = new URLSearchParams(location.search);
   190	  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
