   250	
   251	  /****************************** Sets and Bundles *********************************/
   252	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
   253	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
