   256	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
   257	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
   258	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
