   343	
   344	  /**************** Wishlist ****************/
   345	  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
   346	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
   347	
   348	  const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
   349	    const isItemInWishlist = wishlist?.customerProductListItems?.find(
   350	      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
   351	    );
   352	
   353	    if (!isItemInWishlist) {
   354	      createCustomerProductListItem.mutate(
   355	        {
   356	          parameters: {
