   360	            customerId: customerId as string,
   361	          },
   362	          body: {
   363	            // NOTE: API does not respect quantity, it always adds 1
   364	            quantity,
   365	            productId: variant?.productId || product?.id,
   366	            public: false,
   367	            priority: 1,
   368	            type: 'product',
