   373	            toast({
   374	              title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
   375	              status: 'success',
   376	              action: (
   377	                // it would be better if we could use <Button as={Link}>
   378	                // but unfortunately the Link component is not compatible
   379	                // with Chakra Toast, since the ToastManager is rendered via portal
   380	                // and the toast doesn't have access to intl provider, which is a
